import { localizeText, localizeNode } from '@/i18n/localize';
import type { ReactNode } from "react";
import { Link } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import Header from "@/components/clap/Header";
import Footer from "@/components/clap/Footer";
import AppHeader from "@/components/AppHeader";
import { LanguageProvider } from "@/i18n/LanguageContext";
import { useAppMode } from "@/hooks/use-app-mode";
import { communityRequest, type AuthConfig } from "@/lib/community";
import { DEFAULT_LEGAL_POLICY, type LegalPolicy } from "@/lib/legal";

const pages = { cgu: "Conditions générales d’utilisation", confidentialite: "Politique de confidentialité", "mentions-legales": "Mentions légales" };
type Kind = keyof typeof pages;
function Section({ title, children }: { title: string; children: ReactNode }) {
  return <section className="space-y-3 border-t border-ink/15 pt-6"><h2 className="font-display text-2xl tracking-wide">{localizeNode(title)}</h2>{children}</section>;
}
function Publisher({ policy }: { policy: LegalPolicy }) {
  const { publisher: p, hosting: h } = policy;
  return <>
    <Section title={localizeText("Éditeur et responsable du traitement")}>
      <p><strong>{localizeNode(p.name)}</strong>{localizeText(", artiste-auteur exerçant sous la marque ")}{localizeNode(p.brand)}{localizeText(". Directeur de la publication : ")}{localizeNode(p.publicationDirector)}.</p>
      <dl className="grid gap-2 sm:grid-cols-[auto_1fr]"><dt>{localizeText("Adresse professionnelle")}</dt><dd>{localizeNode(p.address)}</dd><dt>{localizeText("SIRET")}</dt><dd>{localizeNode(p.registration)}</dd><dt>{localizeText("Téléphone professionnel")}</dt><dd>{localizeNode(p.phone)}</dd><dt>{localizeText("Contact et droits sur les données")}</dt><dd><a className="underline break-all" href={`mailto:${p.email}`}>{p.email}</a></dd></dl>
    </Section>
    <Section title={localizeText("Hébergement")}><p>{localizeText("Site, application et base de données : ")}<strong>{localizeNode(h.name)}</strong>, {localizeNode(h.address)}{localizeText(". Téléphone : ")}{localizeNode(h.phone)}{localizeText(". Pays d’hébergement déclaré : ")}{localizeNode(h.country)}.</p><p>{localizeText("Le service de messagerie utilisé par le site est fourni par ")}{localizeNode(policy.operations.mailProvider)}{localizeText(", en ")}{localizeNode(policy.operations.mailCountry)}.</p></Section>
  </>;
}
function Terms({ policy, prefix }: { policy: LegalPolicy; prefix: string }) {
  return <>
    <p>{localizeText("Les présentes conditions encadrent l’utilisation du site Clap & Role et de son application installable. Elles constituent le contrat d’utilisation des fonctions communautaires après acceptation lors de la création du compte. La politique de confidentialité décrit séparément les traitements de données.")}</p>
    <Section title={localizeText("1. Le service et l’accès sans compte")}><p>{localizeText("Clap & Role permet de consulter des films et des actualités, de préparer des parties et de créer des héros, ressources, planches A4, couvertures et images. Les fonctions actuellement proposées sont accessibles gratuitement ; ces conditions ne constituent pas des conditions de vente.")}</p><p>{localizeText("La consultation du site et les outils locaux ne nécessitent pas de compte. L’authentification sert à rattacher les commentaires et notes à leur auteur, ainsi que les publications de films ou d’actualités aux personnes autorisées, et à sécuriser ces contributions. La publication de films et d’actualités est actuellement réservée aux administrateurs.")}</p></Section>
    <Section title={localizeText("2. Création et sécurité du compte")}><p>{localizeText("La création du compte nécessite l’acceptation expresse des CGU et la prise de connaissance de la politique de confidentialité. La case correspondante n’est jamais cochée à l’avance. La version de chaque texte, la date et le mode d’inscription sont enregistrés comme preuve.")}</p><p>{localizeText("Le compte utilise un pseudonyme et un mot de passe associé à une adresse email, ou une connexion Google/Discord. L’utilisateur fournit des informations exactes, préserve ses identifiants et signale toute utilisation non autorisée. L’accès par un mineur suppose l’autorisation de son représentant légal lorsque celle-ci est requise.")}</p></Section>
    <Section title={localizeText("3. Commentaires, notes et publications")}>
      <p>{localizeText("Chaque utilisateur est responsable des contenus qu’il publie, transmet ou partage sur le site et dans l’application, notamment ses commentaires, notes, publications de films, textes, images et fichiers. Il doit s’assurer que ces contenus respectent la loi et les droits des tiers. Cette responsabilité ne dispense pas l’éditeur de ses propres obligations légales.")}</p>
      <p>{localizeText("Il est interdit de publier ou de partager un contenu illégal, notamment menaçant, haineux, diffamatoire ou portant atteinte à la vie privée. Sont également interdits le spam, l’usurpation d’identité et les manipulations de notes.")}</p>
      <p>{localizeText("Il est interdit de publier, reproduire, adapter ou partager une œuvre protégée sans disposer des droits ou autorisations nécessaires à cet usage. L’utilisateur doit être titulaire des droits concernés, bénéficier d’une autorisation du titulaire ou d’une licence permettant la publication et le partage envisagés, ou relever d’une exception légale applicable. Il doit respecter les conditions de la licence, notamment la mention de l’auteur, de la source et de la licence lorsque celles-ci sont exigées. Le fait qu’un contenu soit accessible sur Internet, ait été acheté ou soit accompagné du nom de son auteur ne suffit pas, à lui seul, à autoriser sa republication.")}</p>
      <p>{localizeText("Les commentaires et éléments publics du profil sont consultables par les visiteurs. Il est recommandé d’utiliser un pseudonyme et de ne pas publier d’informations personnelles dans les contributions. Le compte permet l’attribution des contributions ; il ne certifie pas l’identité civile de leur auteur.")}</p>
      <p>{localizeText("L’auteur conserve ses droits. En publiant un contenu, il autorise uniquement son hébergement, sa reproduction et son affichage dans le service, ainsi que les adaptations techniques nécessaires à cet affichage, pendant sa mise à disposition. Cette autorisation est non exclusive et ne permet ni la revente du contenu ni son exploitation publicitaire.")}</p>
    </Section>
    <Section title={localizeText("4. Modération et signalements")}><p>{localizeText("Les administrateurs peuvent retirer un contenu illicite ou contraire aux présentes règles, et restreindre ou supprimer un compte lorsque la sécurité du service ou la protection des personnes le justifie. Les mesures doivent être proportionnées au manquement ; une explication est fournie lorsque la loi le prévoit et que la sécurité ou une obligation légale ne s’y oppose pas.")}</p><p>{localizeText("Un signalement ou une contestation peut être adressé à ")}<a className="underline" href={`mailto:${policy.publisher.email}`}>{policy.publisher.email}</a>{localizeText(", en indiquant la page concernée, le contenu litigieux et les motifs de la demande. Les droits de réponse et recours prévus par la loi restent applicables.")}</p></Section>
    <Section title={localizeText("5. Outils, fichiers locaux et salles de jeu")}><p>{localizeText("Les héros, ressources, images et projets des outils sont principalement conservés dans le navigateur ou l’application de l’utilisateur. L’inscription ne déclenche pas leur synchronisation avec un compte. L’utilisateur reste responsable de ses sauvegardes : effacer les données du navigateur, changer d’appareil ou désinstaller l’application peut supprimer les fichiers locaux.")}</p><p>{localizeText("Les exports sont destinés aux usages autorisés par les droits attachés aux contenus. Le partage volontaire d’une fiche ou la participation à une salle transmet les éléments partagés aux destinataires concernés. Il convient de vérifier les contenus et destinataires avant tout partage.")}</p></Section>
    <Section title={localizeText("6. Propriété intellectuelle et disponibilité")}><p>{localizeText("La marque, les textes et créations propres à Clap n Role demeurent protégés par leurs droits respectifs. Les films, illustrations, marques et contributions de tiers restent la propriété de leurs titulaires. Leur présence dans le service n’emporte aucune cession de droits.")}</p><p>{localizeText("Le service peut être interrompu pour maintenance, évolution ou incident. L’éditeur prend des mesures raisonnables de sécurité et de disponibilité, sans garantir l’absence totale d’interruption ou d’erreur. Aucune clause ne limite une responsabilité ou un droit qui ne peut légalement être écarté.")}</p></Section>
    <Section title={localizeText("7. Fermeture du compte et données personnelles")}><p>{localizeText("L’utilisateur peut demander la fermeture de son compte et exercer ses droits à l’adresse professionnelle indiquée ci-dessus. La suppression du compte entraîne celle des sessions, identités de connexion associées, avatar, commentaires, votes et notes conservés dans la base active. Les publications éditoriales peuvent être maintenues, avec suppression de leur rattachement au compte, sous réserve des droits applicables.")}</p><p>{localizeText("Les règles de conservation, les prestataires et les modalités d’exercice des droits figurent dans la ")}<Link className="underline" to={`${prefix}/confidentialite`}>{localizeText("politique de confidentialité")}</Link>{localizeText(". L’acceptation des CGU n’est pas un consentement à la publicité ou à la vente des données.")}</p></Section>
    <Section title={localizeText("8. Évolution des conditions et droit applicable")}><p>{localizeText("La version applicable lors de l’inscription est identifiée sur cette page. Les modifications substantielles sont annoncées avant leur application aux utilisateurs concernés ; elles ne sont pas réputées acceptées rétroactivement. La simple modification d’une date ne vaut pas acceptation d’une nouvelle version.")}</p><p>{localizeText("Le droit français s’applique, sous réserve des règles impératives plus protectrices éventuellement applicables au lieu de résidence de l’utilisateur. Une réclamation peut d’abord être adressée à l’éditeur, sans priver l’utilisateur de ses voies de recours légales ni lui imposer une juridiction dérogatoire.")}</p></Section>
  </>;
}
function Privacy({ policy }: { policy: LegalPolicy }) {
  return <>
    <div className="space-y-3 border-l-4 border-accent bg-accent/5 p-5"><p className="font-bold">{localizeText("Vos données ne sont ni vendues, ni louées, ni échangées à des fins commerciales ou publicitaires.")}</p><p>{localizeText("Le compte sert à identifier le pseudonyme à l’origine d’un commentaire, d’une note ou d’une publication autorisée, et à assurer la sécurité de ces fonctions. Il ne sert pas à établir un profil publicitaire ni à suivre votre navigation à des fins commerciales.")}</p></div>
    <Section title={localizeText("1. Responsable et périmètre")}><p>{localizeText("Le responsable du traitement est ")}{localizeNode(policy.publisher.name)}{localizeText(", pour la marque ")}{localizeNode(policy.publisher.brand)}{localizeText(", joignable à ")}<a className="underline" href={`mailto:${policy.publisher.email}`}>{policy.publisher.email}</a>{localizeText(". Cette politique couvre le site et l’application installable, les comptes, contributions, outils, salles et demandes de contact.")}</p></Section>
    <Section title={localizeText("2. Données, finalités et bases légales")}><div className="overflow-x-auto"><table className="w-full min-w-[560px] border-collapse text-left text-sm"><thead><tr className="border-b-2 border-ink"><th className="p-3">{localizeText("Données")}</th><th className="p-3">{localizeText("Finalité")}</th><th className="p-3">{localizeText("Base légale")}</th></tr></thead><tbody>
      {[['Identifiant du compte, pseudonyme, email si fourni, empreinte sécurisée du mot de passe, identifiants Google/Discord liés', 'Créer le compte, authentifier, récupérer l’accès et gérer le profil', 'Exécution du contrat, article 6 §1 b du RGPD'], ['Commentaires, notes, votes, identifiant de l’auteur, dates et attribution des publications', 'Afficher et attribuer les contributions, gérer leur modification ou modération', 'Exécution du contrat ; intérêt légitime à la modération et à la lutte contre les abus'], ['Version des CGU et de la politique, date et mode d’acceptation', 'Prouver les conditions acceptées à l’inscription', 'Intérêt légitime à la preuve du contrat'], ['Sessions, états de connexion, données techniques et adresse IP pour les limites anti-abus', 'Sécuriser les accès et prévenir les attaques', 'Intérêt légitime à la sécurité du service'], ['Adresse email, sujet et message du formulaire de contact', 'Répondre à la demande et assurer son suivi', 'Intérêt légitime à répondre aux sollicitations ; mesures précontractuelles si la demande le justifie'], ['Fichiers et préférences enregistrés localement ; éléments volontairement partagés en salle', 'Fournir les outils, conserver les choix et permettre la partie demandée', 'Exécution du service demandé']].map(([data, purpose, basis]) => <tr key={data} className="border-b border-ink/15"><td className="p-3 align-top">{localizeNode(data)}</td><td className="p-3 align-top">{localizeNode(purpose)}</td><td className="p-3 align-top">{localizeNode(basis)}</td></tr>)}
    </tbody></table></div><p>{localizeText("Les champs indispensables sont signalés dans les formulaires. Sans identifiant de connexion ou acceptation des conditions, le compte ne peut pas être créé. La description du profil et son avatar sont facultatifs. Les outils locaux restent utilisables sans inscription.")}</p></Section>
    <Section title={localizeText("3. Ce qui est public et ce qui reste privé")}><p>{localizeText("Le pseudonyme, l’avatar, la description publique et les commentaires sont accessibles aux visiteurs. Les notes servent au calcul des moyennes et restent rattachées au compte pour leur gestion et la prévention des doublons. L’adresse email, le mot de passe, les sessions et les preuves d’acceptation ne sont pas publiés.")}</p><p>{localizeText("Les projets locaux ne sont pas automatiquement envoyés au serveur avec le compte. Un export ou partage décidé par l’utilisateur crée une copie dont il contrôle la destination. En salle, les données volontairement partagées deviennent accessibles aux participants autorisés.")}</p></Section>
    <Section title={localizeText("4. Destinataires et absence de commercialisation")}><p>{localizeText("L’accès interne aux données privées est limité à l’éditeur et aux personnes autorisées pour l’exploitation, la sécurité et la modération du service. Aucune donnée n’est cédée à un partenaire pour son propre marketing.")}</p><p>{localizeText("Des prestataires techniques peuvent néanmoins traiter les seules données nécessaires à leur mission : o2switch pour l’hébergement et la messagerie ; Google ou Discord lorsque vous choisissez leur connexion ; Cloudflare Turnstile pour la vérification anti-robot du formulaire de contact, des nouvelles inscriptions et des connexions après trois échecs. Les polices du site sont actuellement chargées depuis Google Fonts, ce qui entraîne une requête technique vers Google, même sans compte.")}</p><p>{localizeText("Google/Discord transmettent un identifiant de connexion et des informations de profil limitées à l’authentification demandée. Le site ne demande pas l’accès aux messages, contacts ou serveurs Discord, et ne stocke pas les jetons d’accès du fournisseur après l’échange d’authentification. Ces fournisseurs appliquent également leurs propres politiques à leurs services.")}</p><p>{localizeText("Les contributions publiques sont, par nature, communiquées aux visiteurs. Une communication peut aussi être imposée par une obligation légale ou une demande légalement fondée d’une autorité compétente. Ces situations se distinguent d’une vente ou d’une transmission commerciale.")}</p></Section>
    <Section title={localizeText("5. Localisation et transferts")}><p>{localizeText("Le site, la base de données et la messagerie sont hébergés en ")}{localizeNode(policy.hosting.country)}{localizeText(" par ")}{localizeNode(policy.hosting.name)}{localizeText(". Google, Discord et Cloudflare peuvent traiter des données dans d’autres pays, notamment hors de l’Espace économique européen. Leurs services ne doivent être utilisés que dans les conditions et avec les garanties requises par le chapitre V du RGPD.")}</p><p>{localizeText("Garanties et modalités vérifiées par l’éditeur : ")}<span className="break-words">{localizeNode(policy.operations.internationalTransfers)}</span>{localizeText(". Les informations et copies des garanties applicables peuvent être demandées au responsable du traitement.")}</p><p className="flex flex-wrap gap-4"><a className="underline" href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">{localizeText("Google")}</a><a className="underline" href="https://discord.com/privacy" target="_blank" rel="noreferrer">{localizeText("Discord")}</a><a className="underline" href="https://www.cloudflare.com/privacypolicy/" target="_blank" rel="noreferrer">{localizeText("Cloudflare")}</a></p></Section>
    <Section title={localizeText("6. Durées de conservation")}><ul className="list-disc space-y-2 pl-5"><li>{localizeText("Compte, profil et preuve d’acceptation : pendant l’existence du compte, jusqu’à sa suppression, sous réserve d’une conservation distincte effectivement requise par la loi ou un litige identifié.")}</li><li>{localizeText("Commentaires, notes et votes : jusqu’à leur retrait, la suppression du compte ou celle du contenu concerné. Les publications éditoriales peuvent subsister sans rattachement au compte supprimé.")}</li><li>{localizeText("Sessions de connexion : 30 jours maximum ; états temporaires OAuth : 10 minutes ; liens de réinitialisation du mot de passe : 30 minutes. Les entrées expirées sont purgées au prochain traitement des routes concernées.")}</li><li>{localizeText("Protection anti-robot des comptes : compteur d’échecs lié à une empreinte de l’adresse réseau, conservé au maximum trente minutes après le dernier échec, puis expiré ; remise à zéro après une connexion par mot de passe réussie. Preuve temporaire de vérification pour une inscription Google/Discord : cinq minutes avant son utilisation, puis liée à l’état OAuth pendant sa validité de dix minutes. Les entrées expirées sont purgées lors des requêtes.")}</li><li>{localizeText("Contact : le temps de traiter la demande et ses suites ; une correspondance ne peut être maintenue au-delà sans nécessité documentée ou obligation légale.")}</li><li>{localizeText("Salles : état de jeu conservé sur l’appareil du MJ et dans ses exports .clapSalle. Le serveur garde uniquement les accès et les informations de mise en relation en mémoire ; une salle inactive disparaît de la liste après 45 secondes et son accès expire après 90 secondes sans présence du MJ. Les signaux expirent après 90 secondes ; les purges interviennent lors des requêtes.")}</li><li>{localizeText("Journaux techniques : ")}{localizeNode(policy.operations.technicalLogsRetention)}.</li><li>{localizeText("Copies de sauvegarde serveur : ")}{localizeNode(policy.operations.backupsRetention)}{localizeText(". Une restauration doit réappliquer les suppressions demandées avant remise en service.")}</li><li>{localizeText("Données locales de l’application : jusqu’à leur suppression par l’utilisateur ou le navigateur. L’éditeur ne peut pas effacer à distance les exports enregistrés sur un appareil.")}</li></ul></Section>
    <Section title={localizeText("7. Cookies, stockage local et sécurité")}><p>{localizeText("Le cookie de session est destiné à l’authentification. Un cookie temporaire lie la connexion Google/Discord au navigateur qui l’a demandée ; un autre conserve pendant cinq minutes au maximum la preuve de vérification anti-robot nécessaire à une nouvelle inscription externe. Le stockage local et IndexedDB conservent les préférences, fichiers de travail et aperçus ; le cache de l’application permet son fonctionnement hors ligne.")}</p><p>{localizeText("Ces mécanismes fonctionnels ne servent pas à la publicité. Aucun dispositif de publicité ciblée ou de profilage commercial n’est mis en œuvre par le code de l’application. Les services externes identifiés ci-dessus peuvent effectuer leurs propres traitements techniques, décrits dans leurs politiques. Tout ajout ultérieur d’un traceur non nécessaire devra faire l’objet d’une information et, lorsque la loi l’exige, d’un consentement préalable distinct.")}</p><p>{localizeText("Les mots de passe sont stockés sous forme d’empreintes sécurisées avec sel. Les accès et permissions sont contrôlés côté serveur. Ces mesures réduisent les risques sans garantir une sécurité absolue.")}</p></Section>
    <Section title={localizeText("8. Vos droits et réclamations")}><p>{localizeText("Dans les conditions du RGPD, vous pouvez demander l’accès, la rectification, l’effacement, la limitation, la portabilité des données concernées et vous opposer à un traitement fondé sur l’intérêt légitime. Lorsqu’un traitement repose effectivement sur un consentement facultatif, celui-ci peut être retiré sans effet rétroactif. La case d’inscription ne constitue pas un consentement général à tous les traitements.")}</p><p>{localizeText("Adressez votre demande à ")}<a className="underline" href={`mailto:${policy.publisher.email}`}>{policy.publisher.email}</a>{localizeText(" en précisant votre compte et le droit exercé. Une justification d’identité ne sera demandée qu’en cas de doute raisonnable et de manière proportionnée. Une réponse doit intervenir en principe sous un mois ; une prolongation légalement justifiée doit vous être notifiée dans ce délai.")}</p><p>{localizeText("Vous pouvez également adresser une réclamation à la ")}<a className="underline" href="https://www.cnil.fr/fr/plaintes" target="_blank" rel="noreferrer">{localizeText("CNIL")}</a>{localizeText(". Aucune décision produisant un effet juridique à votre égard n’est prise sur le seul fondement d’un profilage automatisé par ce service.")}</p></Section>
  </>;
}
function LegalInner({ kind, appView }: { kind: Kind; appView: boolean }) {
  const config = useQuery({ queryKey: ["auth-config"], queryFn: () => communityRequest<AuthConfig>("/auth/config") });
  const policy = config.data?.legal ?? DEFAULT_LEGAL_POLICY;
  const prefix = appView ? "/app" : "";
  return <div className="min-h-screen bg-paper text-foreground">{localizeNode(appView ? <AppHeader title={localizeText("Informations légales")} /> : <Header />)}<main className={`container max-w-4xl pb-20 ${appView ? "pt-24 sm:pt-10" : "pt-28 md:pt-36"}`}>
    <nav aria-label={localizeText("Informations légales")} className="mb-8 flex flex-wrap gap-3 text-sm">{Object.entries(pages).map(([key, title]) => <Link key={key} to={`${prefix}/${key}`} aria-current={kind === key ? "page" : undefined} className={`border-b-2 py-2 ${kind === key ? "border-accent font-bold" : "border-transparent hover:border-ink/30"}`}>{localizeNode(title)}</Link>)}</nav>
    <h1 className="font-display text-4xl sm:text-5xl">{localizeNode(pages[kind])}</h1><p className="mb-8 mt-3 text-xs text-foreground/60">{localizeText("Mise à jour : ")}{localizeNode(policy.updatedAt)}{localizeText(" · Version ")}{localizeNode(kind === "confidentialite" ? policy.privacyVersion : policy.termsVersion)}</p>
    {localizeNode(!policy.ready && <aside role="note" className="mb-8 border-2 border-ink/25 bg-paper-dark/30 p-4 text-sm">{localizeText("Version en préparation : les variables professionnelles et techniques restent à compléter.")}{localizeNode(policy.registrationOpen ? " Les inscriptions sont temporairement ouvertes pour les tests." : " Les nouvelles inscriptions sont temporairement fermées.")}</aside>)}
    <article className="space-y-7 font-sans text-[15px] leading-7">{localizeNode(kind === "cgu" ? <><Terms policy={policy} prefix={prefix} /><Publisher policy={policy} /></> : kind === "confidentialite" ? <Privacy policy={policy} /> : <><p>{localizeText("Informations relatives au site Clap & Role et à son application installable, édités sous la marque Clap n Role.")}</p><Publisher policy={policy} /></>)}</article>
  </main>{localizeNode(!appView && <Footer />)}</div>;
}
export default function Legal({ kind, appView = false }: { kind: Kind; appView?: boolean }) {
  const installed = useAppMode();
  return <LanguageProvider><LegalInner kind={kind} appView={appView || installed} /></LanguageProvider>;
}
